const { test, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawnSync } = require('child_process');

const script = path.join(__dirname, 'index.js');
let dir;

const cli = (...args) => {
  const r = spawnSync('node', [script, ...args], { cwd: dir, encoding: 'utf8' });
  return { code: r.status, out: r.stdout.trim(), err: r.stderr.trim() };
};
const todos = () => JSON.parse(fs.readFileSync(path.join(dir, 'todos.json'), 'utf8'));

beforeEach(() => { dir = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-')); });
afterEach(() => { fs.rmSync(dir, { recursive: true, force: true }); });

test('add creates a todo with correct fields', () => {
  const r = cli('add', 'Buy groceries');
  assert.strictEqual(r.code, 0);
  const [t] = todos();
  assert.strictEqual(t.id, 1);
  assert.strictEqual(t.text, 'Buy groceries');
  assert.strictEqual(t.completed, false);
  assert.ok(!isNaN(Date.parse(t.createdAt)));
  assert.strictEqual(new Date(t.createdAt).toISOString(), t.createdAt);
});

test('add auto-increments ids, even after deletion', () => {
  cli('add', 'a'); cli('add', 'b'); cli('delete', '2'); cli('add', 'c');
  assert.deepStrictEqual(todos().map((t) => t.id), [1, 3]);
});

test('add without text fails', () => {
  const r = cli('add');
  assert.strictEqual(r.code, 1);
  assert.match(r.err, /Missing todo text/);
  assert.ok(!fs.existsSync(path.join(dir, 'todos.json')));
});

test('add with blank text fails', () => {
  assert.strictEqual(cli('add', '   ').code, 1);
});

test('list on empty shows message', () => {
  const r = cli('list');
  assert.strictEqual(r.code, 0);
  assert.strictEqual(r.out, 'No todos found.');
});

test('list shows id, status and text', () => {
  cli('add', 'one'); cli('add', 'two'); cli('complete', '2');
  const r = cli('list');
  assert.strictEqual(r.out, '1 [ ] one\n2 [x] two');
});

test('complete marks todo done', () => {
  cli('add', 'one');
  const r = cli('complete', '1');
  assert.strictEqual(r.code, 0);
  assert.strictEqual(todos()[0].completed, true);
});

test('complete missing id / invalid id / unknown id', () => {
  cli('add', 'one');
  assert.match(cli('complete').err, /Missing todo id/);
  assert.match(cli('complete', 'abc').err, /Invalid id/);
  assert.match(cli('complete', '-1').err, /Invalid id/);
  const r = cli('complete', '99');
  assert.strictEqual(r.code, 1);
  assert.match(r.err, /not found/);
  assert.strictEqual(todos()[0].completed, false);
});

test('delete removes todo', () => {
  cli('add', 'one'); cli('add', 'two');
  const r = cli('delete', '1');
  assert.strictEqual(r.code, 0);
  assert.deepStrictEqual(todos().map((t) => t.text), ['two']);
});

test('delete missing id / invalid id / unknown id', () => {
  assert.match(cli('delete').err, /Missing todo id/);
  assert.match(cli('delete', 'x').err, /Invalid id/);
  assert.match(cli('delete', '5').err, /not found/);
});

test('unknown or missing command fails with usage', () => {
  assert.strictEqual(cli('bogus').code, 1);
  assert.match(cli('bogus').err, /Unknown command/);
  const r = cli();
  assert.strictEqual(r.code, 1);
  assert.match(r.err, /Usage/);
});

test('corrupt todos.json is treated as empty', () => {
  fs.writeFileSync(path.join(dir, 'todos.json'), 'not json');
  assert.strictEqual(cli('list').out, 'No todos found.');
});

